// Safe environment variable retrieval that won't crash in browser-only environments
const getEnv = (key: string) => {
  try {
    if (typeof process !== 'undefined' && process.env) {
      return process.env[key];
    }
  } catch (e) {
    // Ignore ReferenceErrors
  }
  return undefined;
};

