  // --- Profile State ---
  const [profileForm, setProfileForm] = useState({
      name: '',
      headline: '',
      subHeadline: '',
      email: '',
      avatarUrl: ''
  });
  const [avatarFile, setAvatarFile] = useState<File | null>(null);

  // --- Projects State ---
  const [editingProject, setEditingProject] = useState<any | null>(null); // null = list mode, object = edit mode (empty obj = create)
  const [projectForm, setProjectForm] = useState({
      title: '',
      description: '',
      tags: '',
      liveLink: '',
      githubLink: '',
      image: ''
  });
  const [projectImageFile, setProjectImageFile] = useState<File | null>(null);

  // --- Settings State ---
  const [dbUrl, setDbUrl] = useState('');
  const [dbKey, setDbKey] = useState('');

  // Init Data from Context
  useEffect(() => {
    if (personalInfo) {
        setProfileForm({
            name: personalInfo.name,
            headline: personalInfo.headline,
            subHeadline: personalInfo.subHeadline,
            email: personalInfo.email,
            avatarUrl: personalInfo.avatarUrl
        });
    }
  }, [personalInfo]);

  useEffect(() => {
    setDbUrl(localStorage.getItem('REACT_APP_SUPABASE_URL') || '');
    setDbKey(localStorage.getItem('REACT_APP_SUPABASE_ANON_KEY') || '');
  }, []);

  const handleLogout = async () => {
    if (supabase) await supabase.auth.signOut();
    navigate('/login');
  };

  const showToast = () => {
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 2000);
  }

  // --- Handlers: Profile ---

  const handleProfileSave = async () => {
    setIsSaving(true);
    try {
        if (!supabase) {
             // Demo mode simulation
            await new Promise(r => setTimeout(r, 1000));
        } else {
            let finalAvatarUrl = profileForm.avatarUrl;

            if (avatarFile) {
                finalAvatarUrl = await uploadImage(avatarFile);
            }

            // Upsert profile. Assuming ID 1 for single profile.
            const { error } = await supabase.from('profile').upsert({
                id: 1,
                name: profileForm.name,
                headline: profileForm.headline,
                sub_headline: profileForm.subHeadline,
                email: profileForm.email,
                avatar_url: finalAvatarUrl
            });
            if (error) throw error;
        }

        await refreshData();
        showToast();
    } catch (e: any) {
        alert("Error saving profile: " + e.message);
    } finally {
        setIsSaving(false);
    }
  };

  // --- Handlers: Projects ---

  const openProjectEditor = (project?: any) => {
      if (project) {
          setEditingProject(project);
