          const { error } = await supabase.from('projects').delete().eq('id', id);
          if (error) { alert(error.message); return; }
          await refreshData();
      }
  };

  const handleProjectSave = async () => {
      setIsSaving(true);
      try {
          if (!supabase) {
              await new Promise(r => setTimeout(r, 1000));
