            <Route path="/login" element={<Login />} />
            <Route path="/admin" element={<AdminDashboard />} />
            {/* Fallback route to redirect to home if path doesn't match */}
            <Route path="*" element={<MainPortfolio />} />
          </Routes>
        </main>
    )
}

