                        initial={{ pathLength: 0, opacity: 0, strokeWidth: 1.5 }}
                        animate={{ 
                            pathLength: 1, 
                            opacity: [1, 1, 0],
                            strokeWidth: [1.5, 3, 0.5] // Pulsing width
                        }}
                        transition={{ duration: 0.3, ease: "easeOut" }}
                    />
                ))}

                {/* Impact Flash at Center */}
                <motion.circle 
                    cx="50" cy="50" r="2"
                    fill="white"
                    initial={{ scale: 0 }}
                    animate={{ scale: [0, 40], opacity: [1, 0] }}
                    transition={{ duration: 0.4 }}
                />
              </svg>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

