// --- Sub-Component: Decryption Text Effect ---
const DecryptionText: React.FC<{ text: string; start: boolean }> = ({ text, start }) => {
    const [displayText, setDisplayText] = useState("");
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%^&*";

    useEffect(() => {
        if (!start) return;

        let iteration = 0;
        let interval: any = null;

        interval = setInterval(() => {
            setDisplayText(prev => 
                text.split("").map((letter, index) => {
                    if (index < iteration) {
                        return text[index];
                    }
                    return chars[Math.floor(Math.random() * chars.length)];
                }).join("")
            );

            if (iteration >= text.length) {
                clearInterval(interval);
            }

            iteration += 1 / 3; // Speed of decoding
        }, 30);

        return () => clearInterval(interval);
    }, [start, text]);

    // Initial placeholder before animation starts
    if (!start) return <span className="opacity-0">{text}</span>;

    return <span>{displayText}</span>;
}

// --- Sub-Component: Energy Border SVG ---
const EnergyBorder: React.FC<{ start: boolean, children: React.ReactNode }> = ({ start, children }) => {
    return (
        <div className="relative p-1">
            <motion.svg 
                className="absolute inset-0 w-full h-full pointer-events-none"
                viewBox="0 0 100 100" 
                preserveAspectRatio="none"
            >
                <motion.rect 
                    x="0" y="0" width="100" height="100" rx="2" ry="2"
                    fill="none"
                    stroke="#22d3ee" // Cyan-400
                    strokeWidth="0.5"
                    strokeDasharray="10 400" // A small dash traveling around
                    strokeDashoffset="0"
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={start ? { 
                        pathLength: 1, 
                        opacity: [0, 1, 0.5, 1],
                        strokeDashoffset: [0, -400]
                    } : {}}
                    transition={{ 
                        pathLength: { duration: 0.5, delay: 0.2 },
                        opacity: { duration: 0.5, delay: 0.2 },
                        strokeDashoffset: { duration: 3, repeat: Infinity, ease: "linear" }
                    }}
                />
            </motion.svg>
            {children}
        </div>
    )
}

