                  <div className="text-xl md:text-2xl text-gray-400 leading-relaxed font-normal tracking-wide max-w-2xl min-h-[3rem]">
                    {internalStart && (
                        <motion.p
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 1.0, duration: 0.8 }} // Wait for decryption to mostly finish
                        >
                          {personalInfo.subHeadline}
                        </motion.p>
                    )}
                  </div>

                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={internalStart ? { opacity: 1, y: 0 } : {}}
                    transition={{ delay: 1.5, duration: 0.5 }}
                    className="mt-12 flex gap-6 justify-center"
                  >
                     <a href="#projects" onClick={(e) => handleShockNavigation(e, '#projects')} className="group relative px-8 py-3 bg-white text-black font-sans font-bold text-sm tracking-widest uppercase overflow-hidden">
