const MainPortfolio: React.FC<{ startHeroAnim: boolean }> = ({ startHeroAnim }) => {
  return (
    <>
      <Navbar />
      <div className="flex flex-col gap-0">
        {/* Pass the animation signal to Hero */}
        <Hero startAnimation={startHeroAnim} />
        <Skills />
        <Projects />
        <Resume />
        <Blogs />
        <Contact />
      </div>
    </>
  );
};

const AppContent: React.FC = () => {
    const location = useLocation();
    const isAdminRoute = location.pathname.startsWith('/admin') || location.pathname === '/login';

    // Intro State
    const [showIntro, setShowIntro] = useState(false);
    const [triggerShatter, setTriggerShatter] = useState(false);
    const [introComplete, setIntroComplete] = useState(false);

    // Initial Intro Logic
    useEffect(() => {
        const hasSeenIntro = sessionStorage.getItem('shatter_intro_seen');
        if (!hasSeenIntro && !isAdminRoute) {
            setShowIntro(true);

            // 1. Wait for user to absorb the white screen (0.8s)
            // 2. Trigger the shatter
            const t = setTimeout(() => {
                setTriggerShatter(true);
            }, 800);

            sessionStorage.setItem('shatter_intro_seen', 'true');
            return () => clearTimeout(t);
        } else {
            // If seen, start hero immediately
            setIntroComplete(true);
        }
    }, [isAdminRoute]);

    const handleIntroComplete = () => {
        setShowIntro(false);
        setIntroComplete(true); // Signal Hero to power up
    };

    // Force system cursor on Admin/Login pages
    useEffect(() => {
        if (isAdminRoute) {
            document.body.style.cursor = 'auto';
        } else {
            document.body.style.cursor = 'none';
        }
        return () => { document.body.style.cursor = 'none'; };
    }, [isAdminRoute]);

    return (
        <main className="relative min-h-screen w-full overflow-x-hidden selection:bg-light-accent selection:text-white dark:selection:bg-dark-accent dark:selection:text-black">
          {!isAdminRoute && <CustomCursor />}
          {!isAdminRoute && <ScrollProgress />}

          {/* The Shattered Reality Intro */}
          {showIntro && (
              <ShatteredGlassIntro 
                  triggerShatter={triggerShatter} 
                  onComplete={handleIntroComplete} 
              />
          )}

          <Routes>
            <Route path="/" element={<MainPortfolio startHeroAnim={introComplete} />} />
            <Route path="/login" element={<Login />} />
            <Route path="/admin" element={<AdminDashboard />} />
            <Route path="*" element={<MainPortfolio startHeroAnim={introComplete} />} />
          </Routes>
        </main>
    )
}

const App: React.FC = () => {
  return (
    <Router>
      <PortfolioProvider>
        <AppContent />
      </PortfolioProvider>
    </Router>
  );
};

export default App;

