      avatarUrl: ''
  });
  const [avatarFile, setAvatarFile] = useState<File | null>(null);

  // --- Projects State ---
  const [editingProject, setEditingProject] = useState<any | null>(null); 
  const [projectForm, setProjectForm] = useState({
      title: '',
      description: '',
      tags: '',
      liveLink: '',
      githubLink: '',
      image: ''
  });
  const [projectImageFile, setProjectImageFile] = useState<File | null>(null);

  // --- Resume State ---
  const [editingResume, setEditingResume] = useState<any | null>(null);
  const [resumeForm, setResumeForm] = useState({
      type: 'work',
      title: '',
      company: '',
      period: '',
      description: '',
      tags: ''
  });

  // --- Certificates State ---
  const [editingCertificate, setEditingCertificate] = useState<any | null>(null);
  const [certificateForm, setCertificateForm] = useState({
      title: '',
      issuer: '',
      date: '',
      link: '',
      image: ''
  });
  const [certificateImageFile, setCertificateImageFile] = useState<File | null>(null);

  // --- Blogs / Medium State ---
  const [mediumUsername, setMediumUsername] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  // --- Settings State ---
  const [dbUrl, setDbUrl] = useState('');
  const [dbKey, setDbKey] = useState('');
  const [isConnecting, setIsConnecting] = useState(false);

  // AUTH CHECK: Ensure user is logged in if Supabase is connected
  useEffect(() => {
    const checkSession = async () => {
      if (!supabase) return;
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        setIsAuthenticated(false);
      } else {
        setIsAuthenticated(true);
      }
    };
    checkSession();
  }, []);

  // 1. Load Data on Mount & Updates
  // Prevent overwriting form if user is currently editing (simple check)
  useEffect(() => {
    if (personalInfo && !isSaving) {
        setProfileForm({
            name: personalInfo.name,
            headline: personalInfo.headline,
            subHeadline: personalInfo.subHeadline,
            email: personalInfo.email,
            avatarUrl: personalInfo.avatarUrl
        });
    }
  }, [personalInfo, isSaving]);

  // Fetch Profile ID specifically to ensure we update the correct row
  useEffect(() => {
      const fetchProfileId = async () => {
          if (!supabase) return;
          try {
            const { data } = await supabase.from('profile').select('id').limit(1).maybeSingle();
            if (data) setProfileId(data.id);
          } catch (e) { console.error(e); }
      };
      fetchProfileId();
  }, []);

  useEffect(() => {
