                        {activeTab === 'certificates' && (editingCertificate ? (editingCertificate.id ? 'Edit Certificate' : 'New Certificate') : 'Certificates')}
                        {activeTab === 'resume' && (editingResume ? (editingResume.id ? 'Edit Entry' : 'New Entry') : 'Resume / History')}
