export const Login: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [isNetworkError, setIsNetworkError] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setIsNetworkError(false);

    // Fallback mode logic for demo since Supabase might not be connected
    if (!supabase) {
        if(email === 'yadavdipu296@gmail.com' && password === 'fortknox') {
            navigate('/admin');
        } else {
            setError('Demo Mode: Use yadavdipu296@gmail.com / fortknox');
        }
        setLoading(false);
        return;
    }

    const { error } = await (supabase.auth as any).signInWithPassword({
      email,
      password,
    });

    if (error) {
      let errorMessage = error.message;

      // Detect and translate connection issues
      if (errorMessage.includes('NetworkError') || errorMessage.includes('Failed to fetch')) {
        setIsNetworkError(true);
        errorMessage = "Connection Failed: Unable to reach database. This usually happens if the Project URL is incorrect (e.g. using the Dashboard URL) or an AdBlocker is blocking requests.";
      }

      setError(errorMessage);
    } else {
      navigate('/admin');
    }
    setLoading(false);
  };

  const handleResetConnection = () => {
      if (confirm("This will clear your saved Supabase URL and Key. You will revert to Demo Mode. Continue?")) {
        localStorage.removeItem('REACT_APP_SUPABASE_URL');
        localStorage.removeItem('REACT_APP_SUPABASE_ANON_KEY');
        window.location.reload();
      }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-dark-text flex items-center justify-center p-4 relative overflow-hidden">
        {/* Background Grid */}
        <div className="absolute inset-0 bg-grid-dark bg-[length:40px_40px] opacity-20 pointer-events-none" />

        <motion.div 
            initial={{ opacity: 0, scale: 0.9 }}
            animate={{ opacity: 1, scale: 1 }}
