import React, { useEffect, useRef } from 'react';

export const SentientGrid: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;

    // Grid Configuration - TIGHTER AND BRIGHTER
    const spacing = 45;
    const rows = Math.ceil(height / spacing);
    const cols = Math.ceil(width / spacing);
    const mouse = { x: -1000, y: -1000 };

    // Physics Configuration - MORE REACTIVE
    const stiffness = 0.1;
    const damping = 0.88; 
    const reach = 250; // Larger influence radius

    interface Point {
      x: number;
      y: number;
      ox: number; 
      oy: number; 
      vx: number;
      vy: number;
    }

    const points: Point[] = [];

    // Initialize Points
    for (let y = 0; y <= rows; y++) {
      for (let x = 0; x <= cols; x++) {
        const px = x * spacing;
        const py = y * spacing;
        points.push({ x: px, y: py, ox: px, oy: py, vx: 0, vy: 0 });
      }
    }

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;
    };

    const handleResize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('resize', handleResize);

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      const colsCount = cols + 1;

      // Update Physics
      for (let i = 0; i < points.length; i++) {
        const p = points[i];

        // Distance to mouse
        const dx = mouse.x - p.x;
        const dy = mouse.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        // Repulsion force
        if (dist < reach) {
          const force = (reach - dist) / reach;
          const angle = Math.atan2(dy, dx);

          // Move points AWAY from mouse
          const pushX = Math.cos(angle) * force * 8; 
          const pushY = Math.sin(angle) * force * 8;
          p.vx -= pushX;
          p.vy -= pushY;
        }

        // Spring force (Return to origin)
        const dxHome = p.ox - p.x;
        const dyHome = p.oy - p.y;

        p.vx += dxHome * stiffness;
        p.vy += dyHome * stiffness;

        // Apply friction
        p.vx *= damping;
        p.vy *= damping;

        // Move
        p.x += p.vx;
        p.y += p.vy;
      }

      // Draw Grid Lines
      ctx.beginPath();
      ctx.strokeStyle = 'rgba(41, 216, 255, 0.35)'; // Higher base opacity
      ctx.lineWidth = 1; // Thicker lines

      for (let i = 0; i < points.length; i++) {
        const p = points[i];

        // Draw Dot at intersection
        // ctx.fillStyle = 'rgba(41, 216, 255, 0.5)';
        // ctx.fillRect(p.x - 1, p.y - 1, 2, 2);

        // Draw to right neighbor
        if ((i + 1) % colsCount !== 0 && i + 1 < points.length) {
          const next = points[i + 1];
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(next.x, next.y);
        }
        // Draw to bottom neighbor
        if (i + colsCount < points.length) {
          const bottom = points[i + colsCount];
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(bottom.x, bottom.y);
        }
      }
      ctx.stroke();

      // Opacity mask (Vignette)
      const gradient = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, width);
      gradient.addColorStop(0, 'rgba(2, 6, 23, 0)'); // Transparent center
      gradient.addColorStop(0.8, 'rgba(2, 6, 23, 0.5)'); 
      gradient.addColorStop(1, 'rgba(2, 6, 23, 1)'); // Solid edges

      ctx.fillStyle = gradient;
      ctx.fillRect(0,0,width,height);

      requestAnimationFrame(animate);
    };

    animate();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  // Removed low opacity class, handling opacity in canvas context for better control
  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 z-0 pointer-events-auto mix-blend-screen" 
    />
  );
};

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';

interface NeuralLinkProps {
  activeId: number | null;
  cardRefs: React.MutableRefObject<Map<number, HTMLDivElement | null>>;
}

export const NeuralLink: React.FC<NeuralLinkProps> = ({ activeId, cardRefs }) => {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [targetPos, setTargetPos] = useState({ x: 0, y: 0 });
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  useEffect(() => {
    if (activeId === null) {
      setIsVisible(false);
      return;
    }

    const card = cardRefs.current.get(activeId);
    if (card) {
      const rect = card.getBoundingClientRect();
      // Target the center of the card
      setTargetPos({ 
        x: rect.left + rect.width / 2, 
        y: rect.top + rect.height / 2
      });
      setIsVisible(true);
    }
  }, [activeId, mousePos]);

  if (!isVisible) return null;

  return (
    <div className="fixed inset-0 pointer-events-none z-[100] overflow-visible">
        <svg className="w-full h-full overflow-visible">
            <defs>
                <linearGradient id="neural-gradient" gradientUnits="userSpaceOnUse" x1={mousePos.x} y1={mousePos.y} x2={targetPos.x} y2={targetPos.y}>
                    <stop offset="0%" stopColor="#29D8FF" stopOpacity="0.8" />
                    <stop offset="50%" stopColor="#FFFFFF" stopOpacity="1" />
                    <stop offset="100%" stopColor="#29D8FF" stopOpacity="0.8" />
                </linearGradient>
                <filter id="strong-glow">
                    <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
                    <feMerge>
                        <feMergeNode in="coloredBlur"/>
                        <feMergeNode in="SourceGraphic"/>
                    </feMerge>
                </filter>
            </defs>

            {/* Mouse Reticle (The "Jack" plug) */}
            <motion.circle 
                cx={mousePos.x} 
                cy={mousePos.y} 
                r="6" 
                stroke="#29D8FF" 
                strokeWidth="2" 
                fill="none" 
                animate={{ scale: [1, 1.5, 1], opacity: [0.5, 1, 0.5] }}
                transition={{ duration: 1, repeat: Infinity }}
            />
             <motion.circle 
                cx={mousePos.x} 
                cy={mousePos.y} 
                r="2" 
                fill="#fff" 
            />

            {/* The Main Connecting Line */}
            <motion.path
                d={`M ${mousePos.x} ${mousePos.y} L ${targetPos.x} ${targetPos.y}`}
                stroke="url(#neural-gradient)"
                strokeWidth="2"
                fill="none"
                filter="url(#strong-glow)"
                initial={{ pathLength: 0, opacity: 0 }}
                animate={{ pathLength: 1, opacity: 1 }}
                transition={{ duration: 0.3 }}
            />

            {/* Data Packets traveling the line */}
            {/* Packet 1 */}
            <motion.circle r="4" fill="#fff" filter="drop-shadow(0 0 8px #29D8FF)">
                <animateMotion 
                    dur="0.6s" 
                    repeatCount="indefinite"
                    path={`M ${mousePos.x} ${mousePos.y} L ${targetPos.x} ${targetPos.y}`}
                />
            </motion.circle>

            {/* Packet 2 (Delayed) */}
            <motion.circle r="3" fill="#29D8FF">
                <animateMotion 
                    dur="0.6s" 
                    begin="0.3s"
                    repeatCount="indefinite"
                    path={`M ${mousePos.x} ${mousePos.y} L ${targetPos.x} ${targetPos.y}`}
                />
            </motion.circle>

            {/* Target Lock Ring on Card */}
            <motion.g transform={`translate(${targetPos.x}, ${targetPos.y})`}>
                <motion.circle 
                    r="20" 
                    stroke="#29D8FF" 
                    strokeWidth="1" 
                    fill="none" 
                    strokeDasharray="5 5"
                    animate={{ rotate: 360, scale: [1, 1.1, 1] }}
                    transition={{ rotate: { duration: 4, repeat: Infinity, ease: "linear" }, scale: { duration: 1, repeat: Infinity } }}
                />
                <circle r="4" fill="#29D8FF" className="animate-ping" />
            </motion.g>
        </svg>
    </div>
  );
};

