import React, { useEffect, useRef } from 'react';
import { useScroll, useTransform, motion } from 'framer-motion';

export const ParticleMetamorphosis: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // --- CONFIGURATION ---
    const PARTICLE_COUNT = window.innerWidth < 768 ? 1500 : 3500; // Performance optimization for mobile
    const CONNECTION_DIST = 40; // Max distance to draw lines (optional, heavy on perf)
    const MOUSE_REPULSION = 150;
    const ROTATION_SPEED = 0.002;
    const TRANSITION_SPEED = 0.05;

    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;

    // --- STATE ---
    let currentScrollY = 0;
    let targetShape = 0; // 0: Head, 1: Brain, 2: Globe
    const mouse = { x: 0, y: 0, isActive: false };

    // --- PARTICLE SYSTEM ---
    // We store positions as flat arrays for performance [x, y, z, tx, ty, tz]
    // p = current position, t = target position
    interface Particle {
      x: number; y: number; z: number;
      tx: number; ty: number; tz: number;
      vx: number; vy: number; vz: number;
      color: string;
    }

    const particles: Particle[] = [];

    // Initialize Particles
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      particles.push({
        x: (Math.random() - 0.5) * 800,
        y: (Math.random() - 0.5) * 800,
        z: (Math.random() - 0.5) * 800,
        tx: 0, ty: 0, tz: 0,
        vx: 0, vy: 0, vz: 0,
        color: Math.random() > 0.8 ? '#29D8FF' : '#ffffff' // 20% Accent, 80% White
      });
    }

    // --- SHAPE GENERATORS (Math) ---

    // 1. Cyber Head (Approximate Sculpted Sphere)
    const setHeadShape = () => {
      const radius = 280;
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const p = particles[i];
        // Spherical distribution
        const u = Math.random() * Math.PI;
        const v = Math.random() * Math.PI * 2;

        let x = radius * Math.sin(u) * Math.cos(v);
        let y = radius * Math.sin(u) * Math.sin(v);
        let z = radius * Math.cos(u);

        // Morph Sphere into Head-like shape
        // Jaw Taper
        if (y > 0) {
            x *= 0.85; 
            z *= 0.9;
        }
        // Chin
        if (y > 150) {
            x *= 0.7;
        }
        // Nose Protrusion
        if (y > -50 && y < 100 && z > 0) {
            if (Math.abs(x) < 60) {
                z += 40 * (1 - Math.abs(x)/60);
            }
        }

        p.tx = x;
        p.ty = y;
        p.tz = z;
      }
    };

    // 2. Digital Brain (Two Hemispheres)
    const setBrainShape = () => {
      const radius = 220;
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const p = particles[i];

        // Split into Left/Right hemispheres
        const hemisphere = i % 2 === 0 ? 1 : -1;

        const u = Math.random() * Math.PI;
        const v = Math.random() * Math.PI * 2; // Full sphere coord

        // Ellipsoid for brain lobe
        let x = (radius * 0.8) * Math.sin(u) * Math.cos(v);
        let y = (radius * 0.9) * Math.sin(u) * Math.sin(v);
        let z = (radius * 1.1) * Math.cos(u);

        // Shift hemispheres apart
        x += hemisphere * 60;

        // Add "Fold" noise
        const noise = Math.sin(x * 0.1) * Math.cos(y * 0.1) * 10;
        x += noise;
        y += noise;
        z += noise;

        p.tx = x;
        p.ty = y;
        p.tz = z;
      }
    };

    // 3. Networked Globe (Hollow Sphere)
    const setGlobeShape = () => {
        const radius = 350;
        for (let i = 0; i < PARTICLE_COUNT; i++) {
          const p = particles[i];
          const u = Math.random() * Math.PI * 2;
          const v = Math.acos((Math.random() * 2) - 1);

          p.tx = radius * Math.sin(v) * Math.cos(u);
          p.ty = radius * Math.sin(v) * Math.sin(u);
          p.tz = radius * Math.cos(v);
        }
    };

    // Initialize with Head
    setHeadShape();

    // --- ANIMATION LOOP ---
    let rotationAngle = 0;

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      // 1. Determine Shape based on Scroll
      // This is a rough check. In a real app, use IntersectionObserver for precision.
      const scrollPct = currentScrollY / (document.body.scrollHeight - window.innerHeight);

      let nextShape = 0;
      if (scrollPct > 0.15 && scrollPct < 0.5) nextShape = 1; // Skills Section
      if (scrollPct >= 0.5) nextShape = 2; // Projects/Contact

      if (nextShape !== targetShape) {
          targetShape = nextShape;
          if (targetShape === 0) setHeadShape();
          if (targetShape === 1) setBrainShape();
          if (targetShape === 2) setGlobeShape();
      }

      // Center of screen
      const cx = width / 2;
      const cy = height / 2;

      // Interaction Rotation
      const targetRotX = (mouse.y - cy) * 0.0001;
      const targetRotY = (mouse.x - cx) * 0.0001;

      rotationAngle += ROTATION_SPEED;

      // Sort particles by Z for depth (simple painter's algorithm approx)
      // Note: Sorting 4000 items every frame in JS is heavy. 
      // We skip sorting for "Points" style as opacity handles it well enough.

      ctx.fillStyle = '#fff';

      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const p = particles[i];

        // 2. Physics: Move P towards T (Easing)
        p.x += (p.tx - p.x) * TRANSITION_SPEED;
        p.y += (p.ty - p.y) * TRANSITION_SPEED;
        p.z += (p.tz - p.z) * TRANSITION_SPEED;

        // 3. Physics: Mouse Repulsion (Force Field)
        // We project 3D point to 2D first to check mouse distance? 
        // No, check 3D distance roughly assuming mouse is at z=-500 (viewer)
        // Easier: Just project first, then check 2D dist.

        // ROTATION
        let x = p.x;
        let y = p.y;
        let z = p.z;

        // Rotate Y (Auto + Mouse)
        const angleY = rotationAngle + targetRotY;
        const cosY = Math.cos(angleY);
        const sinY = Math.sin(angleY);
        let x1 = x * cosY - z * sinY;
        let z1 = z * cosY + x * sinY;

        // Rotate X (Mouse)
        const angleX = targetRotX;
        const cosX = Math.cos(angleX);
        const sinX = Math.sin(angleX);
        let y1 = y * cosX - z1 * sinX;
        let z2 = z1 * cosX + y * sinX;

        // PROJECTION (Perspective)
        const scale = 800 / (800 + z2); // 800 is camera distance
        const projX = x1 * scale + cx;
        const projY = y1 * scale + cy;

        // Mouse Interaction (2D Screen Space Repulsion)
        const dx = mouse.x - projX;
        const dy = mouse.y - projY;
        const dist = Math.sqrt(dx*dx + dy*dy);

        if (dist < MOUSE_REPULSION) {
            const force = (MOUSE_REPULSION - dist) / MOUSE_REPULSION;
            const angle = Math.atan2(dy, dx);
            // Push the *actual 3D target* away temporarily? 
            // Or just visual offset? Visual offset is smoother.
            // Let's modify the projected drawing coordinate for the "Explosion" look.

            // To make it permanent/physics-based, we'd modify p.vx/vy. 
            // Let's keep it elastic visual only for stability.
            // Actually, modifying p.x/p.y creates the "scatter" effect.

            p.x -= Math.cos(angle) * force * 50;
            p.y -= Math.sin(angle) * force * 50;
        }

        // DRAW
        const alpha = (scale - 0.5) * 1.5; // Fade distant particles
        if (alpha > 0) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha;
            const size = 1.5 * scale;
            ctx.beginPath();
            ctx.arc(projX, projY, size, 0, Math.PI * 2);
            ctx.fill();
        }
      }

      requestAnimationFrame(animate);
    };

    const animationId = requestAnimationFrame(animate);

    // --- EVENT LISTENERS ---
    const handleScroll = () => {
        currentScrollY = window.scrollY;
    };

    const handleMouseMove = (e: MouseEvent) => {
        mouse.x = e.clientX;
        mouse.y = e.clientY;
        mouse.isActive = true;
    };

    const handleResize = () => {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    };

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  return (
    <motion.canvas
      ref={canvasRef}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
      className="fixed inset-0 z-[-1] pointer-events-none bg-[#020617]"
      style={{
          background: 'radial-gradient(circle at center, #0f172a 0%, #020617 100%)' // Subtle vignette
      }}
    />
  );
};

import React, { useState, useEffect } from 'react';
