          const v = Math.acos((Math.random() * 2) - 1);

          p.tx = radius * Math.sin(v) * Math.cos(u);
          p.ty = radius * Math.sin(v) * Math.sin(u);
          p.tz = radius * Math.cos(v);
        }
    };

    // Initialize with Field
    setCosmicField();

    // --- ANIMATION LOOP ---
    let rotationAngle = 0;

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      const scrollPct = currentScrollY / (document.body.scrollHeight - window.innerHeight || 1);

      let nextShape = 0;
      if (scrollPct > 0.15 && scrollPct < 0.6) nextShape = 1; 
      if (scrollPct >= 0.6) nextShape = 2; 

      if (nextShape !== targetShape) {
          targetShape = nextShape;
          if (targetShape === 0) setCosmicField();
          if (targetShape === 1) setBrainShape();
          if (targetShape === 2) setGlobeShape();
      }

      const cx = width / 2;
      const cy = height / 2;

      // Interaction Rotation
      const targetRotX = (mouse.y - cy) * 0.00005;
      const targetRotY = (mouse.x - cx) * 0.00005;

      rotationAngle += ROTATION_SPEED;

      for (let i = 0; i < PARTICLE_COUNT; i++) {
        const p = particles[i];

        // Physics
        p.x += (p.tx - p.x) * TRANSITION_SPEED;
        p.y += (p.ty - p.y) * TRANSITION_SPEED;
        p.z += (p.tz - p.z) * TRANSITION_SPEED;

        // Rotation
        let x = p.x;
        let y = p.y;
        let z = p.z;

        const angleY = rotationAngle + targetRotY;
        const cosY = Math.cos(angleY);
        const sinY = Math.sin(angleY);
        let x1 = x * cosY - z * sinY;
        let z1 = z * cosY + x * sinY;

        const angleX = targetRotX;
        const cosX = Math.cos(angleX);
        const sinX = Math.sin(angleX);
        let y1 = y * cosX - z1 * sinX;
        let z2 = z1 * cosX + y * sinX;

        // Projection
        const scale = 800 / (1000 + z2); 
        const projX = x1 * scale + cx;
        const projY = y1 * scale + cy;

        // Mouse Repulsion
        const dx = mouse.x - projX;
        const dy = mouse.y - projY;
        const dist = Math.sqrt(dx*dx + dy*dy);

        let drawX = projX;
        let drawY = projY;

        if (dist < MOUSE_REPULSION) {
            const force = (MOUSE_REPULSION - dist) / MOUSE_REPULSION;
            const angle = Math.atan2(dy, dx);
            drawX -= Math.cos(angle) * force * 30;
            drawY -= Math.sin(angle) * force * 30;
        }

        // Draw with heavily reduced opacity
        const depthAlpha = (scale - 0.2);
        const finalAlpha = Math.min(depthAlpha * p.baseAlpha, 0.4); 

        if (finalAlpha > 0) {
            ctx.fillStyle = p.color;
            ctx.globalAlpha = finalAlpha;
            const size = p.size * scale;
            ctx.beginPath();
            ctx.arc(drawX, drawY, size, 0, Math.PI * 2);
            ctx.fill();
        }
      }

      requestAnimationFrame(animate);
    };

    const animationId = requestAnimationFrame(animate);

    const handleScroll = () => { currentScrollY = window.scrollY; };
    const handleMouseMove = (e: MouseEvent) => { mouse.x = e.clientX; mouse.y = e.clientY; };
    const handleResize = () => { 
        width = canvas.width = window.innerWidth; 
        height = canvas.height = window.innerHeight; 
        if(targetShape === 0) setCosmicField(); // Re-calc field on resize
    };

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  return (
    <motion.canvas
      ref={canvasRef}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 1 }}
      className="fixed inset-0 z-[-1] pointer-events-none bg-[#020617]"
      style={{
          background: 'radial-gradient(circle at center, #0f172a 0%, #020617 80%)' 
      }}
    />
  );
};

import React, { useEffect, useState, useRef } from 'react';

interface NeuralLinkProps {
  activeId: number | null;
  cardRefs: React.MutableRefObject<Map<number, HTMLDivElement | null>>;
}

export const NeuralLink: React.FC<NeuralLinkProps> = ({ activeId, cardRefs }) => {
  const [coords, setCoords] = useState<{ x1: number, y1: number, x2: number, y2: number } | null>(null);
  const mouseRef = useRef({ x: 0, y: 0 });
  const rafRef = useRef<number>(0);

  // Track mouse position globally
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current = { x: e.clientX, y: e.clientY };
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // Animation Loop to update line coordinates
  useEffect(() => {
    if (activeId === null) {
      setCoords(null);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      return;
    }

    const update = () => {
      const card = cardRefs.current.get(activeId);
      if (card) {
        const rect = card.getBoundingClientRect();
        // Calculate center of the target card
        const targetX = rect.left + rect.width / 2;
        const targetY = rect.top + rect.height / 2;

        setCoords({
            x1: mouseRef.current.x,
            y1: mouseRef.current.y,
            x2: targetX,
            y2: targetY
        });
      }
      rafRef.current = requestAnimationFrame(update);
    };

    update(); // Start loop

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [activeId, cardRefs]);

  if (!coords) return null;

  // --- MATH FOR SKETCHY CURVE ---

  // Calculate midpoint
  const midX = (coords.x1 + coords.x2) / 2;
  const midY = (coords.y1 + coords.y2) / 2;

  // Calculate vector
  const dx = coords.x2 - coords.x1;
  const dy = coords.y2 - coords.y1;
  const dist = Math.sqrt(dx * dx + dy * dy);

  // Add a slight curve (Bézier Control Point)
  // We use perpendicular offset to create an arc
  // Offset depends on distance to make it look proportional
  const curvature = Math.min(dist * 0.15, 60); 

  // Deterministic direction for curve so it doesn't flip wildly
  const offsetDir = (coords.x2 > coords.x1) ? 1 : -1;

  // Control Point logic: Midpoint + Perpendicular Vector
  const cpX = midX - (dy / dist) * curvature * offsetDir;
  const cpY = midY + (dx / dist) * curvature * offsetDir;

  // Primary Line (Strong)
  const pathD = `M ${coords.x1} ${coords.y1} Q ${cpX} ${cpY} ${coords.x2} ${coords.y2}`;

  // Secondary Line (Messy/Sketchy Duplicate)
  // Slight random offset for the control point of the ghost line
  const pathD2 = `M ${coords.x1} ${coords.y1} Q ${cpX + 15} ${cpY - 15} ${coords.x2} ${coords.y2}`;

  return (
    <div className="fixed inset-0 pointer-events-none z-[9999] overflow-visible">
        <svg className="w-full h-full overflow-visible">
            <defs>
                {/* 
                   Sketch Filter: Creates a rough, jagged edge on the stroke.
                   This mimics the texture of a pencil or marker on paper.
                */}
                <filter id="sketch-roughness">
                    <feTurbulence type="fractalNoise" baseFrequency="0.02" numOctaves="3" result="noise" />
                    <feDisplacementMap in="SourceGraphic" in2="noise" scale="4" />
                </filter>
            </defs>

            {/* Target Area Scribble */}
            <g transform={`translate(${coords.x2}, ${coords.y2})`}>
                <circle 
                    r="25" 
                    stroke="#29D8FF" 
                    strokeWidth="1.5" 
                    fill="none" 
                    filter="url(#sketch-roughness)" 
                    opacity="0.5" 
                />
                 <circle 
                    r="18" 
                    stroke="white" 
                    strokeWidth="1" 
                    fill="none" 
                    filter="url(#sketch-roughness)" 
                    opacity="0.3" 
                    strokeDasharray="4 2"
                />
            </g>

            {/* Main Connecting Line (Cyan Marker Style) */}
            <path 
                d={pathD} 
                stroke="#29D8FF" 
                strokeWidth="2.5" 
                fill="none" 
                filter="url(#sketch-roughness)"
                strokeLinecap="round"
                opacity="0.8"
            />

            {/* Ghost Line (White Pencil Style) */}
            <path 
                d={pathD2} 
                stroke="white" 
                strokeWidth="1" 
                fill="none" 
                filter="url(#sketch-roughness)"
                opacity="0.4"
                strokeDasharray="8 4"
            />

            {/* Mouse Scribble */}
            <g transform={`translate(${coords.x1}, ${coords.y1})`}>
                {/* A small 'X' or crosshair at the mouse */}
                <path 
                    d="M -6 -6 L 6 6 M -6 6 L 6 -6" 
                    stroke="#29D8FF" 
                    strokeWidth="2" 
                    filter="url(#sketch-roughness)" 
                />
            </g>
        </svg>
    </div>
  );
};

